const KEY='evening-campaign-records-v1';
export function loadCampaigns(levels,legacy){let raw={};try{raw=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{}const result={};for(const [i,level]of levels.entries()){const r=raw&&typeof raw==='object'?raw[level.name]:null;if(r?.completed===true)result[level.name]={completed:true,wins:Number.isSafeInteger(r.wins)&&r.wins>=0?r.wins:0,bestOvertime:Number.isFinite(r.bestOvertime)&&r.bestOvertime>=0?r.bestOvertime:null,lastCompleted:typeof r.lastCompleted==='string'?r.lastCompleted:null};else if(Number.isFinite(legacy?.[i])&&legacy[i]>=level.waves)result[level.name]={completed:true,wins:0,bestOvertime:null,lastCompleted:null};}return result;}
export function saveCampaigns(records){try{localStorage.setItem(KEY,JSON.stringify(records));return true;}catch{return false;}}
export function completeCampaign(records,name,overtime){const old=records[name];records[name]={completed:true,wins:(old?.wins||0)+1,bestOvertime:old?.bestOvertime==null?overtime:Math.min(old.bestOvertime,overtime),lastCompleted:new Date().toISOString()};return saveCampaigns(records);}
